async function seedProducts() {
  console.log('🌱 Starting Posticky product seed (Admin SDK)...\n')

  const allProducts = [...STICKERS, ...TSHIRTS]
  let count = 0

  for (const product of allProducts) {
    try {
      const slug = product.name
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, '-')

      const docRef = db.collection('products').doc(slug)

      await docRef.set({
        ...product,
        slug,
        createdAt: admin.firestore.FieldValue.serverTimestamp(),
        updatedAt: admin.firestore.FieldValue.serverTimestamp(),
      })

      count++

      console.log(
        `✅ [${count}/${allProducts.length}] ${product.name} → ${docRef.id}`
      )
    } catch (err) {
      console.error(`❌ Failed: ${product.name} →`, err.message)
    }
  }

  console.log(`\n🎉 Done! ${count}/${allProducts.length} products added to Firestore.`)

  process.exit(0)
}

seedProducts()